static int js_pi_finish_consumed_value(JSContext *ctx, JSValue *slot,
                                      JSValue value)
{
    JSNativeAsyncPending owned = { false, JS_UNDEFINED };
    JSValue operand = *slot;

    *slot = value;
    js_native_async_release(ctx, operand, &owned);
    if (owned.present) {
        value = *slot;
        *slot = JS_UNDEFINED;
        js_native_async_release(ctx, value, &owned);
        JS_Throw(ctx, owned.reason);
        return -1;
    }
    return JS_IsException(value) ? -1 : 0;
}

static void js_native_async_take_pending(JSContext *ctx, JSNativeAsyncPending *owned)
{
    while (JS_HasException(ctx)) {
        JSValue next = JS_GetException(ctx);
        if (!owned->present) {
            owned->present = true;
            owned->reason = next;
        } else if (JS_PiNativePendingReplace(ctx->rt, owned->reason, next)) {
            JSValue displaced = owned->reason;
            owned->reason = next;
            JS_FreeValue(ctx, displaced);
        } else {
            JS_FreeValue(ctx, next);
        }
    }
}

static void js_native_async_release(JSContext *ctx, JSValue value,
                                    JSNativeAsyncPending *owned)
{
    js_native_async_take_pending(ctx, owned);
    JS_FreeValue(ctx, value);
    js_native_async_take_pending(ctx, owned);
}

JSValue JS_GetPropertyValue(JSContext *ctx, JSValueConst this_obj,
                            JSValue prop)
{
    JSAtom atom;
    JSValue ret;
    uint32_t tag;

    tag = JS_VALUE_GET_TAG(this_obj);
    if (likely(tag == JS_TAG_OBJECT)) {
        if (JS_VALUE_GET_TAG(prop) == JS_TAG_INT) {
            JSObject *p = JS_VALUE_GET_OBJ(this_obj);
            uint32_t idx = JS_VALUE_GET_INT(prop);
            JSValue val;
            /* fast path for array and typed array access */
            if (js_get_fast_array_element(ctx, p, idx, &val))
                return val;
        }
    } else if (unlikely(tag == JS_TAG_NULL || tag == JS_TAG_UNDEFINED)) {
        // per spec: not allowed to call ToPropertyKey before ToObject
        // so we must ensure to not invoke JS anything that's observable
        // from JS code
        atom = JS_ValueToAtomInternal(ctx, prop, JS_TO_STRING_NO_SIDE_EFFECTS);
        JS_FreeValue(ctx, prop);
        if (unlikely(atom == JS_ATOM_NULL))
            return JS_EXCEPTION;
        if (tag == JS_TAG_NULL) {
            JS_ThrowTypeErrorAtom(ctx, "cannot read property '%s' of null", atom);
        } else {
            JS_ThrowTypeErrorAtom(ctx, "cannot read property '%s' of undefined", atom);
        }
        JS_FreeAtom(ctx, atom);
        return JS_EXCEPTION;
    }
    atom = JS_ValueToAtom(ctx, prop);
    JS_FreeValue(ctx, prop);
    if (unlikely(atom == JS_ATOM_NULL))
        return JS_EXCEPTION;
    ret = JS_GetProperty(ctx, this_obj, atom);
    JS_FreeAtom(ctx, atom);
    return ret;
}

static bool js_get_fast_array_element(JSContext *ctx, JSObject *p,
                                      uint32_t idx, JSValue *pval)
{
    switch(p->class_id) {
    case JS_CLASS_ARRAY:
    case JS_CLASS_ARGUMENTS:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_dup(p->u.array.u.values[idx]);
        return true;
    case JS_CLASS_MAPPED_ARGUMENTS:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_dup(*p->u.array.u.var_refs[idx]->pvalue);
        return true;
    case JS_CLASS_INT8_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_int32(p->u.array.u.int8_ptr[idx]);
        return true;
    case JS_CLASS_UINT8C_ARRAY:
    case JS_CLASS_UINT8_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_int32(p->u.array.u.uint8_ptr[idx]);
        return true;
    case JS_CLASS_INT16_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_int32(p->u.array.u.int16_ptr[idx]);
        return true;
    case JS_CLASS_UINT16_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_int32(p->u.array.u.uint16_ptr[idx]);
        return true;
    case JS_CLASS_INT32_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_int32(p->u.array.u.int32_ptr[idx]);
        return true;
    case JS_CLASS_UINT32_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_uint32(p->u.array.u.uint32_ptr[idx]);
        return true;
    case JS_CLASS_BIG_INT64_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = JS_NewBigInt64(ctx, p->u.array.u.int64_ptr[idx]);
        return true;
    case JS_CLASS_BIG_UINT64_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = JS_NewBigUint64(ctx, p->u.array.u.uint64_ptr[idx]);
        return true;
    case JS_CLASS_FLOAT16_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_float64(fromfp16(p->u.array.u.fp16_ptr[idx]));
        return true;
    case JS_CLASS_FLOAT32_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_float64(p->u.array.u.float_ptr[idx]);
        return true;
    case JS_CLASS_FLOAT64_ARRAY:
        if (unlikely(idx >= js_array_data_count(p))) return false;
        *pval = js_float64(p->u.array.u.double_ptr[idx]);
        return true;
    default:
        return false;
    }
}

